    distanceLabel: 'Approximately 5 miles round trip', paddleTime: '3–6 hours depending on level, shallow water, underwater obstacles, current, and retrace distance', summary: 'A bounded Harrisville same-access outing on the NJDEP-marked Oswego River water trail.', statusText: 'Planning route only. The official water-trail guide is canoe/kayak-only, warns of shallow water and underwater obstacles, and directs paddlers to check current USGS levels.', gaugeSiteId: '01410000', gaugeSiteName: 'Oswego River at Harrisville, NJ', thresholdSource: { label: 'NJDEP Wading River and Oswego River Water Trails guide', url: wadingOswegoUrl, provider: 'local' }, routeType: 'recreational', difficulty: 'moderate', riskLevel: 'caution', hazards: ['low_water', 'fast_rise', 'cold_water', 'strainers', 'access_uncertain'], safetyNotes: [...commonSafety, 'Treat the route as an out-and-back with a hard return to Harrisville. Do not rely on marsh, bridge, or forest-road shoreline for emergency extraction.'], shuttle: 'No shuttle; launch and return at Harrisville after confirming the current marked route, parking, carry, and waterline. A same-access route requires a conservative turnaround.', permits: 'Follow Wharton State Forest access rules, current closures, New Jersey boating/PFD rules, and the official canoe/kayak-only water-trail restrictions.', camping: 'No on-route camping is claimed for the same-access outing. Use separately reserved Wharton campgrounds only if the current route and access plan support it.', campingClassification: 'nearby_basecamp', accessCaveats: ['Harrisville is an access-area/station anchor, not proof of a usable ramp on launch day.', 'The same-access boundary prevents use of unreviewed downstream banks as a take-out.', 'Do not treat the direct USGS station as a safe-water cutoff without visual inspection and route-specific guidance.'], watchFor: ['USGS 01410000 level and trend, actual Harrisville water depth, recent rain, and debris', 'shallow water, underwater obstacles, strainers, cold water, and storms', 'parking/carry, current park closures, daylight, and hard Harrisville return'], evidenceNotes: [{ label: 'Named moving-water corridor', value: 'NJDEP-marked Oswego River water trail with Harrisville access context', note: 'The official guide provides the water-trail, obstacle, canoe/kayak-only, and level-check posture.', sourceUrl: wadingOswegoUrl }, { label: 'Direct gauge evidence', value: 'USGS 01410000 Oswego River at Harrisville is at the route context, but no numeric recreational threshold is claimed', note: 'Use current readings and visual conditions together.', sourceUrl: 'https://waterdata.usgs.gov/monitoring-location/USGS-01410000/' }, { label: 'Public access posture', value: 'Harrisville same-access boundary', note: 'The coordinate is a near-water access anchor; confirm the current launch/carry and do not infer alternate take-outs.', sourceUrl: wadingOswegoUrl }, { label: 'Camping posture', value: 'Nearby basecamp only', note: 'No informal camping entitlement is implied.', sourceUrl: whartonUrl }], sourceLinks: [{ label: 'NJDEP Wading and Oswego water trails', url: wadingOswegoUrl, provider: 'local' }, { label: 'NJDEP Wharton State Forest', url: whartonUrl, provider: 'local' }, { label: 'USGS Oswego River at Harrisville', url: 'https://waterdata.usgs.gov/monitoring-location/USGS-01410000/', provider: 'usgs' }], contextImageUrl: pineBarrensImage, contextImageNote: 'Same-water-family Pine Barrens context image; it does not certify current Oswego River conditions.',
