    accessPoints: [{ id: 'south-branch-raritan-sunnyside', name: 'Sunnyside Section canoe access at Kiceniuk Road', latitude: 40.578792, longitude: -74.88412, mileFromStart: 0, note: 'Hunterdon County identifies Sunnyside as a South Branch Reservation section, says the area just beyond the parking lot provides river access for canoes, and recommends Sunnyside as a canoe/kayak access site. The official NJDEP monitoring record is an on/near-water Kiceniuk Road anchor; verify the carry, waterline, parking, and current park rules before unloading.' }, { id: 'south-branch-raritan-stanton-station', name: 'Stanton Station Road public access', latitude: 40.5725, longitude: -74.86769, mileFromStart: 1.5, note: 'Hunterdon County recommends Stanton Station as a canoe/kayak access site, and NJDEP lists a public Stanton Station Road bridge parking area with a foot path to the river. The official monitoring record supplies an on/near-water Stanton Station coordinate; confirm the actual landing, parking, bridge traffic, and take-out footing on the day of travel.' }],
    distanceLabel: 'Approximately 1.5 river miles', paddleTime: '1–2.5 hours depending on discharge, shallow sections, obstacles, current, and breaks', summary: 'A short planning-only South Branch Raritan reach linking two Hunterdon County public canoe/kayak access sections in the South Branch Nature Preserve.', statusText: 'Planning route only. Hunterdon County explicitly recommends Sunnyside and Stanton Station for canoe/kayak access; use the direct Stanton USGS gauge with recent rain, visual depth, wood, bridge, and access checks. No numeric recreational cutoff is transferred.', gaugeSiteId: '01397000', gaugeSiteName: 'South Branch Raritan River at Stanton, NJ', gaugeKind: 'direct', thresholdSource: { label: 'Hunterdon County South Branch Nature Preserve canoe/kayak guide and NJDEP public access listing', url: southBranchHunterdonUrl, provider: 'local' }, routeType: 'recreational', difficulty: 'moderate', riskLevel: 'caution', hazards: ['low_water', 'fast_rise', 'cold_water', 'strainers', 'dam', 'access_uncertain'], safetyNotes: [...commonSafety, 'Hunterdon County describes this corridor as canoeable but the river has shallow sections, tree and stone obstructions, current, and fishing traffic. Scout the launch and route before committing, wear the PFD continuously, and portage or turn around at any dam, bridge obstruction, strainer, or unsafe shallow.'], shuttle: 'Stage the vehicle at Stanton Station only after confirming current public parking, footpath, landing, and take-out footing, then launch at Sunnyside. The short shuttle does not authorize stopping on bridge shoulders, landing on private banks, or using a park section outside its posted hours.', permits: 'Follow Hunterdon County park sunrise-to-sunset rules, current county notices, NJDEP public-access rules, New Jersey boating/PFD requirements, seasonal hunting warnings, and any water-quality or closure advisory. No route-specific permit is claimed.', camping: 'No on-route camping is identified. Hunterdon County park access is day-use oriented; use separately managed lodging or a lawful designated campground and do not camp on the reservation shoreline.', campingClassification: 'nearby_basecamp', accessCaveats: ['Hunterdon County identifies the named sections as public recreation areas and canoe/kayak access, but current carry, waterline, parking, and legal landing conditions must be confirmed before unloading.', 'The county brochure says park properties are carry-in/carry-out and the Sunnyside guide notes no restroom facilities; plan for self-contained logistics.', 'The South Branch corridor has seasonal hunting activity and bridge/road crossings. Wear blaze orange during the county’s September–February hunting period or confine visits to Sundays as posted, and never use a bridge shoulder or private bank as an alternate access.'], watchFor: ['USGS 01397000 direct Stanton discharge, gage height, recent rainfall, and visual river conditions', 'shallow water, fast rises, cold water, strainers, stone/tree obstructions, bridges, fishing traffic, and any dam or portage', 'Sunnyside parking/carry/waterline, Stanton footpath/landing, sunrise-to-sunset access, seasonal hunting, daylight, and shuttle failure'], evidenceNotes: [{ label: 'Named moving-water corridor', value: 'South Branch Raritan River from Sunnyside Section to Stanton Station', note: 'Hunterdon County’s current South Branch Reservation guide describes canoeing/kayaking and explicitly recommends Sunnyside and Stanton Station access sites.', sourceUrl: southBranchHunterdonUrl }, { label: 'Public endpoint evidence', value: 'Sunnyside canoe access at Kiceniuk Road and Stanton Station Road public access', note: 'Hunterdon County identifies both public reservation sections for recreation; NJDEP independently lists Stanton Station Road public access and the official monitoring records provide on/near-water anchors. Verify the actual landing and current signs.', sourceUrl: southBranchAccessUrl }, { label: 'Direct flow evidence', value: 'USGS 01397000 South Branch Raritan River at Stanton, NJ', note: 'The continuous-record station is at the Stanton Station area. Use current discharge and stage with visual depth, recent rain, wood, bridge conditions, and cold-water judgment; no numeric recreational cutoff is inferred.', sourceUrl: 'https://waterdata.usgs.gov/monitoring-location/USGS-01397000/' }, { label: 'Camping posture', value: 'Nearby basecamp only', note: 'The county materials establish day-use park recreation and carry-in/carry-out expectations, not shoreline camping rights.', sourceUrl: southBranchHunterdonUrl }], sourceLinks: [{ label: 'Hunterdon County South Branch Nature Preserve guide', url: southBranchHunterdonUrl, provider: 'local' }, { label: 'NJDEP public access listing', url: southBranchAccessUrl, provider: 'local' }, { label: 'NJDEP Kiceniuk Road coordinate record', url: southBranchKiceniukCoordinateUrl, provider: 'local' }, { label: 'NJDEP Stanton Station coordinate record', url: southBranchStantonCoordinateUrl, provider: 'local' }, { label: 'USGS South Branch Raritan at Stanton', url: 'https://waterdata.usgs.gov/monitoring-location/USGS-01397000/', provider: 'usgs' }], contextImageUrl: southBranchImage, contextImageNote: 'Approved U.S. Geological Survey South Branch Raritan River at Stanton image; it is same-river context and does not certify current Sunnyside or Stanton access, flow, hazards, or waterline.',
