    accessPoints: [{ id: 'alloway-quinton-kayak-launch', name: 'Quinton Alloway Road kayak launch', latitude: 39.54859651333707, longitude: -75.4132197621161, mileFromStart: 0, note: 'NJDEP’s current public-access inventory identifies QT00115 at Quinton Alloway Road as a Fishing, Boat access and explicitly comments “Kayak launch.” Confirm current launch condition, parking, carry, tidal window, and any posted municipal or wildlife-area restrictions before unloading.' }, { id: 'alloway-hancocks-bridge-ramp', name: 'Hancocks Bridge Front Street municipal boat ramp', latitude: 39.5086111111111, longitude: -75.4605555555556, mileFromStart: 6, note: 'Lower Alloways Creek Township publishes the Hancocks Bridge Front Street ramp as a general-public boat ramp with resident/non-resident registration fees and current operating controls. The coordinate is the official USGS Alloway Creek at Hancocks Bridge estuary station anchor near the named ramp, not a surveyed wetted-edge point; confirm current sticker, parking, carry, waterline, and landing.' }],
    distanceLabel: 'Approximately 6 tidal river miles', paddleTime: '3–6 hours depending on tide, wind, current, shallow sections, traffic, breaks, and the Hancocks Bridge draw schedule', summary: 'A bounded lower Alloway Creek tidal planning reach connecting the NJDEP-listed Quinton kayak launch with the public Hancocks Bridge Front Street municipal ramp.', statusText: 'Planning route only. NJDEP identifies a kayak launch at Quinton Alloway Road; Lower Alloways Creek Township publishes the Hancocks Bridge public ramp and fee/registration controls; USGS 01483050 supplies direct estuary telemetry at the downstream endpoint area. Plan around tide, wind, shallow marsh water, bridge openings, water quality, and current landing conditions; no numeric recreational cutoff is transferred.', gaugeSiteId: '01483050', gaugeSiteName: 'Alloway Creek at Hancocks Bridge, NJ', gaugeKind: 'direct', thresholdSource: { label: 'Lower Alloways Creek Township ramp rules, NJDEP access inventory, and USGS direct estuary monitoring', url: allowayMunicipalRampUrl, provider: 'local' }, routeType: 'recreational', difficulty: 'moderate', riskLevel: 'caution', hazards: ['low_water', 'fast_rise', 'cold_water', 'strainers', 'private_banks', 'urban_water_quality', 'access_uncertain'], safetyNotes: [...commonSafety, 'This is a tidal estuary: forecast tide and wind, expect current reversal, shallow mud, shoals, and marsh-channel navigation, and never treat the USGS station as a local safe-depth or tide cutoff.', 'The Route 540 and Hancocks Bridge draw structures, bridge traffic, floating debris, strainers, and narrow channels require conservative timing and visual scouting. Confirm any required draw opening notice before committing to a bridge-constrained passage, and do not approach bridge machinery or pass against posted restrictions.', 'NJDEP water-quality records identify Alloway Creek reaches with fish-consumption advisories/impairment history. Check current NJDEP advisories, avoid contact with contaminated water, and do not treat tidal exchange as a water-quality clearance.'], shuttle: 'Register and stage at the Hancocks Bridge Front Street municipal ramp only under the township’s current fee/sticker and parking rules; the township prohibits overnight parking. Launch at Quinton Alloway Road after confirming the kayak launch, parking, carry, tide/wind window, and daylight margin. Do not use private marsh banks, bridge shoulders, or unmarked channels as shuttle or bailout access.', permits: 'Follow current NJDEP public-access and water-quality notices, Lower Alloways Creek Township ramp registration/fee and parking rules, New Jersey boating/PFD requirements, NOAA tide and weather guidance, bridge-draw notices, and any posted closure. The public ramp registration does not guarantee a clear paddlecraft landing or a right to camp.', camping: 'No on-route camping is identified. Hancocks Bridge ramp rules prohibit overnight parking, and neither public access point establishes shoreline camping; use separately managed lodging or a lawful designated campground.', campingClassification: 'nearby_basecamp', accessCaveats: ['NJDEP’s inventory explicitly calls the Quinton Alloway Road point a kayak launch, but it is an inventory record rather than a current ramp survey; verify launch surface, parking, carry, waterline, and any seasonal restrictions.', 'The Hancocks Bridge coordinate is the direct USGS estuary station anchor near the township’s named Front Street ramp. Confirm the ramp’s exact wetted-edge landing and current resident/non-resident registration requirements before relying on the endpoint.', 'This route stops at Hancocks Bridge. Do not extend toward Delaware Bay, Artificial Island, private marsh banks, or unreviewed tributary channels without a separate tidal-navigation, endpoint, water-quality, and safety review.'], watchFor: ['USGS 01483050 direct Alloway Creek stage/discharge and field conditions, plus NOAA tide predictions and wind', 'shallow mud, shoals, reversing current, marsh channels, strainers, floating debris, bridge traffic/draws, cold-water immersion, and water-quality advisories', 'Quinton launch and Hancocks Bridge registration/fee, parking/no-overnight rule, carry, waterline, daylight, tide window, and shuttle failure'], evidenceNotes: [{ label: 'Named moving-water corridor', value: 'Alloway Creek tidal reach from Quinton Alloway Road to Hancocks Bridge', note: 'USGS identifies Alloway Creek at Hancocks Bridge as an estuary, and the reviewed public access sources establish a connected named creek between the two endpoint settings.', sourceUrl: allowayAccessUrl }, { label: 'Public endpoint evidence', value: 'NJDEP QT00115 Quinton Alloway Road kayak launch and Lower Alloways Creek Township Hancocks Bridge Front Street public boat ramp', note: 'The NJDEP inventory explicitly comments “Kayak launch.” The township’s current ramp material establishes general-public access, registration fees, and operating controls; both endpoints still require day-of landing confirmation.', sourceUrl: allowayMunicipalRampUrl }, { label: 'On/near-water coordinate evidence', value: 'NJDEP public-access coordinate for QT00115 and USGS 01483050 at Hancocks Bridge', note: 'The Quinton coordinate is from the current NJDEP access layer. The downstream coordinate is the official USGS estuary station anchor near the named municipal ramp, not a surveyed wetted-edge point.', sourceUrl: allowayGaugeUrl }, { label: 'Direct flow and tidal evidence', value: 'USGS 01483050 Alloway Creek at Hancocks Bridge, NJ plus NOAA tide predictions', note: 'Use direct station trend and field conditions with tide, wind, recent rain, shallow-water observations, bridge notices, and visual scouting; no numeric recreational cutoff is inferred.', sourceUrl: allowayGaugeUrl }, { label: 'Camping posture', value: 'Nearby basecamp only', note: 'The township ramp’s no-overnight-parking rule and public-access sources do not establish shoreline camping rights.', sourceUrl: allowayRampRegistrationUrl }], sourceLinks: [{ label: 'NJDEP public-access and kayak-launch inventory', url: allowayAccessUrl, provider: 'local' }, { label: 'Lower Alloways Creek Township Hancocks Bridge boat ramp', url: allowayMunicipalRampUrl, provider: 'local' }, { label: 'Lower Alloways Creek Township ramp registration form', url: allowayRampRegistrationUrl, provider: 'local' }, { label: 'USGS Alloway Creek at Hancocks Bridge', url: allowayGaugeUrl, provider: 'usgs' }, { label: 'NOAA Salem tide predictions', url: allowayTideUrl, provider: 'manual' }], contextImageUrl: allowayImage, contextImageNote: 'Approved public-domain USGS Alloway Creek survey image described as a recon survey heading upstream from the Quinton boat launch and downstream of the Route 540 bridge; it provides same-reach context and does not certify current access, tide, flow, bridge, water-quality, or safety conditions.',
