    distanceLabel: 'Approximately 3.5 river miles', paddleTime: '2–5 hours depending on tide, discharge, wind, shallow water, current, and access carry', summary: 'A bounded public-access transition section on the Rancocas Creek water-trail family from Hainesport to Mount Holly.', statusText: 'Planning route only. The official Rancocas Creek application describes public launches and a tidal/non-tidal connected corridor, but no local safe-depth or tide cutoff is claimed.', gaugeSiteId: '01465850', gaugeSiteName: 'South Branch Rancocas Creek at Vincentown, NJ', thresholdSource: { label: 'NJDEP Rancocas Creek Water Trail application', url: rancocasUrl, provider: 'local' }, routeType: 'recreational', difficulty: 'moderate', riskLevel: 'caution', hazards: ['low_water', 'fast_rise', 'cold_water', 'strainers', 'private_banks', 'urban_water_quality', 'access_uncertain'], safetyNotes: [...commonSafety, 'This route can be affected by tide, wind, recent rain, urban runoff, shallow mud, strainers, and private banks. Do not assume that a freshwater station supplies a local tidal cutoff.', 'Follow current water-quality and storm advisories before entering a creek receiving urban runoff.'], shuttle: 'Stage at the Mount Holly public endpoint only after confirming current parking and legal water exit; launch at Hainesport and do not use private or visual-only bank points as alternates.', permits: 'Follow the current municipal/park landing rules, posted hours/closures, New Jersey boating/PFD requirements, and any water-quality advisories. No route-specific permit is claimed.', camping: 'No on-route camping is identified. Use separately managed lodging or a lawful regional campground; public creek launches do not grant overnight shoreline rights.', campingClassification: 'nearby_basecamp', accessCaveats: ['The NJDEP access layer is an inventory and may include visual/fishing points; the Rancocas water-trail application is the controlling public-launch evidence for this route.', 'Coordinates are near-water anchors and must be checked against the current landing, carry, parking, municipal rules, and waterline.', 'Do not extend from this bounded section into the tidal wishbone, Delaware River, or North Branch trail without a separate tide, endpoint, and safety review.'], watchFor: ['USGS 01465850 proxy trend, tide/wind, recent rain, shallow mud, and debris', 'urban water quality, strainers, private banks, bridges, and missed Mount Holly take-out', 'municipal launch hours, parking, carry, closures, daylight, and shuttle'], evidenceNotes: [{ label: 'Named moving-water corridor', value: 'Rancocas Creek Water Trail, Hainesport to Mount Holly public-access transition', note: 'The official NJDEP application describes the corridor, public municipal access, and connected non-tidal/tidal route family.', sourceUrl: rancocasUrl }, { label: 'Public endpoint evidence', value: 'Hainesport and Mount Holly public-access municipalities, corroborated by NJDEP on/near-water access-layer anchors', note: 'The layer is not treated as sufficient by itself; current facility verification remains required.', sourceUrl: njAccessUrl }, { label: 'Proxy flow and tidal evidence', value: 'USGS 01465850 South Branch Rancocas Creek at Vincentown, clearly labeled upstream proxy plus current tide/weather/water-quality review', note: 'No local numeric threshold is inferred.', sourceUrl: 'https://waterdata.usgs.gov/monitoring-location/USGS-01465850/' }, { label: 'Camping posture', value: 'Nearby basecamp only', note: 'No public-launch camping entitlement is claimed.', sourceUrl: rancocasUrl }], sourceLinks: [{ label: 'NJDEP Rancocas Creek Water Trail application', url: rancocasUrl, provider: 'local' }, { label: 'NJDEP public-access inventory', url: njAccessUrl, provider: 'local' }, { label: 'USGS South Branch Rancocas Creek at Vincentown', url: 'https://waterdata.usgs.gov/monitoring-location/USGS-01465850/', provider: 'usgs' }], contextImageUrl: pineBarrensImage, contextImageNote: 'Approved New Jersey moving-water context image; it does not represent current Rancocas Creek tide, water quality, or access.',
